const { withAndroidColors, withAndroidStyles, AndroidConfig } = require("expo/config-plugins");

const { assignColorValue } = AndroidConfig.Colors;
const { assignStylesValue, getAppThemeGroup } = AndroidConfig.Styles;

/**
 * The window background, and a status bar the app paints itself.
 *
 * `android/` is gitignored and regenerated by `expo prebuild`, so this belongs
 * in a plugin rather than in the generated files.
 *
 * The window background is what shows before the first frame renders, and
 * prebuild sets it to `splashscreen_background`, white. On a dark app that is
 * a white flash, so it is the canvas colour instead.
 *
 * The status bar is transparent and the app draws behind it, which is the only
 * way its colour can follow the theme: an Android 15 target ignores
 * `setStatusBarColor` at runtime, so a colour fixed here would be fixed for
 * every theme. Whether the icons are dark or light is decided at runtime by
 * `expo-status-bar`, which still works, and the top inset keeps content clear
 * of the clock.
 */
const CANVAS = "#0D0E11";

const withDarkSystemChrome = (config) => {
  let next = withAndroidColors(config, (mod) => {
    mod.modResults = assignColorValue(mod.modResults, {
      name: "splashscreen_background",
      value: CANVAS,
    });
    mod.modResults = assignColorValue(mod.modResults, {
      name: "activityBackground",
      value: CANVAS,
    });
    return mod;
  });

  next = withAndroidStyles(next, (mod) => {
    mod.modResults = assignStylesValue(mod.modResults, {
      add: true,
      name: "android:navigationBarColor",
      value: "@android:color/transparent",
      parent: getAppThemeGroup(),
    });
    mod.modResults = assignStylesValue(mod.modResults, {
      add: true,
      name: "android:statusBarColor",
      value: "@android:color/transparent",
      parent: getAppThemeGroup(),
    });
    return mod;
  });

  return next;
};

module.exports = withDarkSystemChrome;
